--
-- Table structure for table `pagos`
--

DROP TABLE IF EXISTS `pagos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pagos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `residente_id` int(11) DEFAULT NULL,
  `unidad_id` int(11) NOT NULL,
  `monto` decimal(10,2) NOT NULL,
  `fecha_pago` date NOT NULL,
  `metodo_pago` varchar(50) NOT NULL,
  `banco_pagador` varchar(100) DEFAULT NULL,
  `banco_receptor` varchar(100) DEFAULT NULL,
  `cuenta_bancaria_id` int(11) DEFAULT NULL,
  `referencia` varchar(100) DEFAULT NULL,
  `referencia_norm` varchar(100) DEFAULT NULL,
  `archivo` varchar(255) NOT NULL,
  `archivo_hash` char(64) DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `estado` varchar(20) DEFAULT 'PENDIENTE',
  `fecha_registro` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  `dup_guard` varchar(191) GENERATED ALWAYS AS (if(`estado` = 'RECHAZADO' or `deleted_at` is not null and `estado` <> 'APROBADO',NULL,if(`referencia_norm` is null or `referencia_norm` = '',concat('S|',`unidad_id`,'|',`fecha_pago`,'|',`monto`),concat('R|',`unidad_id`,'|',`referencia_norm`)))) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pago_dup_guard` (`dup_guard`),
  KEY `residente_id` (`residente_id`),
  KEY `unidad_id` (`unidad_id`),
  KEY `idx_pagos_conciliacion` (`referencia`,`monto`,`estado`),
  KEY `idx_pagos_referencia_norm` (`referencia_norm`),
  KEY `idx_pagos_archivo_hash` (`archivo_hash`),
  CONSTRAINT `pagos_ibfk_1` FOREIGN KEY (`residente_id`) REFERENCES `personas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pagos_ibfk_2` FOREIGN KEY (`unidad_id`) REFERENCES `unidades` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=817 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

